import math

def count_divisors(n):
    """Calculates the number of positive divisors (tau(n))."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates d(n), the number of divisors other than 1 and n."""
    if n <= 1:
        return -1 # Should not happen for positive n in this context, but handles small edge cases
    tau_n = count_divisors(n)
    return tau_n - 2

# 1. Verify existence of a=2 and find a concrete pair
found_a2 = []
N_MAX = 10000
min_a_found = 3 # Initialize higher than possible min

print("--- Searching for a=2 examples ---")
for n in range(1, N_MAX + 1):
    a = d(n)
    if a >= 0:
        n_plus_735 = n + 735
        a_plus = d(n_plus_735)

        if a == a_plus:
            if a == 2:
                found_a2.append((n, n_plus_735))
                if len(found_a2) >= 1:
                    print(f"Found concrete pair for a=2: ({found_a2[0][0]}, {found_a2[0][1]})")
                    break # Only need one pair for verification

# 2. Extend search up to N=10000 to find minimum 'a'
print("\n--- Searching for minimum 'a' up to N=10000 ---")
for n in range(1, N_MAX + 1):
    a = d(n)
    if a >= 0:
        n_plus_735 = n + 735
        a_plus = d(n_plus_735)

        if a == a_plus:
            min_a_found = min(min_a_found, a)

print(f"\nComputational search up to N={N_MAX} found the minimum value a = {min_a_found}")

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# Factor pairs (A, B) of 735
pairs = [(1, 735), (3, 245), (5, 147), (7, 105), (15, 49), (21, 35)]

results = []
for A, B in pairs:
    p = (B - A) // 2
    q = (B + A) // 2
    p_prime = is_prime(p)
    q_prime = is_prime(q)
    results.append({
        'A': A, 'B': B, 'p': p, 'q': q, 'p_prime': p_prime, 'q_prime': q_prime
    })

for res in results:
    print(f"Pair ({res['A']}, {res['B']}): p={res['p']} (Prime: {res['p_prime']}), q={res['q']} (Prime: {res['q_prime']})")
